#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int check_media_change(struct cdrom_device_info *cdi, unsigned long arg) {
    int ret = -ENOSYS;

    if (!cdi || !cdi->ops || !cdi->ops->check_media_change)
        return -ENOSYS;

    if (arg > CDROM_DISC_UNKNOWN)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    ret = cdi->ops->check_media_change(cdi, arg, info);
    if (ret < 0)
        goto out;

    ret = info->media_changed ? 0 : -ENOMEDIUM;

out:
    kfree(info);
    return ret;
}

int check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi->cdi_ioctl || !(cdi->mask |= CDC_PLAY_AUDIO)) {
        return -ENOSYS;
    }

    if (!cdrom_can_eject(cdi)) {
        return -EINVAL;
    }

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info) {
        return -ENOMEM;
    }

    ret = cdrom_read_mechanism_status(cdi, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    if ((arg < 0) || (arg >= CDROM_MAX_DISC)) {
        kfree(info);
        return -EINVAL;
    }

    if (info->disc[arg].inserted) {
        ret = 0;
    } else {
        ret = -ENOMEDIUM;
    }

    kfree(info);
    return ret;
}

#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!(cdi->mask & CDC_MCN) || !cdi->media_changed)
        return -ENOSYS;

    if (arg > CDROM_CD_TRAY)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    int ret = cdi->media_changed(cdi, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    kfree(info);
    return 0;
}

#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->mask & CDC_MEDIA_CHANGED))
        return -ENOSYS;

    if (arg > CDROM_DISC_TRAY && arg != CDROM_MEDIA_CHANGED)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    int ret = cdi->ops->check_media_change(cdi, arg, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    ret = info->media_changed ? 0 : -ENOSYS;
    kfree(info);
    return ret;
}

#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi->ops->check_events)
        return -ENOSYS;

    if (arg >= CDROM_DISC_STATUS_MAX)
        return -EINVAL;

    ret = cdi->ops->check_events(cdi, arg, NULL);

    return ret;
}
